/* --- js/api.js --- */
/* ===============================================
   前后端 API 客户端
   =============================================== */

const Api = {
    baseUrl: '/api',
    requestTimeoutMs: 5000,
    enabled: true,

    init(config = globalThis.__PINYIN_EXPLORER_CONFIG__ || {}) {
        this.baseUrl = String(config.apiBaseUrl || '/api').replace(/\/$/, '') || '/api';
        this.requestTimeoutMs = Math.max(1000, Number(config.requestTimeoutMs) || 5000);
        this.enabled = config.apiEnabled !== false;
    },

    async request(path, options = {}) {
        if (!this.enabled || typeof globalThis.fetch !== 'function') return null;

        const controller = typeof AbortController === 'function' ? new AbortController() : null;
        const timeout = controller
            ? setTimeout(() => controller.abort(), this.requestTimeoutMs)
            : null;

        try {
            const response = await fetch(`${this.baseUrl}/${String(path).replace(/^\//, '')}`, {
                ...options,
                headers: {
                    Accept: 'application/json',
                    ...(options.body ? { 'Content-Type': 'application/json' } : {}),
                    ...(options.headers || {})
                },
                signal: controller?.signal
            });

            if (!response.ok) return null;
            return await response.json();
        } catch {
            // API 同步是增强能力，网络失败不能阻断离线游戏。
            return null;
        } finally {
            if (timeout) clearTimeout(timeout);
        }
    },

    syncGameResult(payload) {
        return this.request('/game-results', {
            method: 'POST',
            body: JSON.stringify(payload)
        });
    },

    health() {
        return this.request('/health');
    }
};


/* --- js/storage.js --- */
/* ===============================================
   本地存储管理
   =============================================== */


const Storage = {
    MODES: ['letters', 'pinyin', 'words'],
    MAX_SCORE: 100000,
    DEFAULT_SETTINGS: {
        soundEnabled: true,
        musicEnabled: true,
        volume: 0.7,
        letterLanguage: 'zh'
    },

    KEYS: {
        USERS: 'pinyin_explorer_users',
        CURRENT_USER: 'pinyin_explorer_current_user',
        SETTINGS: 'pinyin_explorer_settings',
        GAME_COUNT: 'pinyin_explorer_game_count'
    },

    /**
     * 获取所有用户
     */
    getUsers() {
        const data = this.readJson(this.KEYS.USERS, []);
        return Array.isArray(data) ? data.map(user => this.normalizeUser(user)) : [];
    },

    /**
     * 保存用户列表
     */
    saveUsers(users) {
        return this.safeSetItem(this.KEYS.USERS, JSON.stringify(users));
    },

    /**
     * 创建新用户
     */
    createUser(name, avatar) {
        const users = this.getUsers();
        const newUser = {
            id: this.createId(),
            name: String(name ?? '').trim().slice(0, 8),
            avatar: avatar || 'cat',
            totalScore: 0,
            highScores: {
                letters: 0,
                pinyin: 0,
                words: 0
            },
            badges: [],
            errorLetters: {},  // 记录容易错的字母 { 'A': 5, 'B': 3 }
            gamesPlayed: 0,
            createdAt: new Date().toISOString()
        };

        if (!newUser.name) return null;

        users.push(newUser);
        if (!this.saveUsers(users)) return null;
        this.setCurrentUser(newUser.id);

        return newUser;
    },

    /**
     * 获取用户
     */
    getUser(userId) {
        const users = this.getUsers();
        return users.find(u => u.id === userId);
    },

    /**
     * 更新用户数据
     */
    updateUser(userId, updates) {
        const users = this.getUsers();
        const index = users.findIndex(u => u.id === userId);

        if (index !== -1) {
            users[index] = { ...users[index], ...updates };
            return this.saveUsers(users) ? users[index] : null;
        }
        return null;
    },

    /**
     * 记录游戏结果
     */
    recordGameResult(userId, mode, score, correct, wrong, errorLetters = []) {
        const user = this.getUser(userId);
        if (!user || !this.MODES.includes(mode)) return null;

        // 更新总分
        const safeScore = Math.min(this.MAX_SCORE, Math.max(0, Math.round(Number(score) || 0)));
        user.totalScore = Math.max(0, user.totalScore + safeScore);
        user.gamesPlayed += 1;

        // 更新模式最高分
        if (safeScore > (Number(user.highScores[mode]) || 0)) {
            user.highScores[mode] = safeScore;
        }

        // 记录错误字母
        (Array.isArray(errorLetters) ? errorLetters : []).forEach(letter => {
            const normalizedLetter = String(letter ?? '').toUpperCase();
            if (!/^[A-Z]$/.test(normalizedLetter)) return;
            user.errorLetters[normalizedLetter] = (user.errorLetters[normalizedLetter] || 0) + 1;
        });

        // 检查新勋章
        const badge = Utils.getBadge(user.totalScore);
        let newBadge = null;
        if (badge && !user.badges.includes(badge.name)) {
            user.badges.push(badge.name);
            newBadge = badge;
        }

        const updatedUser = this.updateUser(userId, user);

        return { user: updatedUser, newBadge };
    },

    /**
     * 获取用户容易出错的字母（返回前5个）
     */
    getFrequentErrors(userId, limit = 5) {
        const user = this.getUser(userId);
        if (!user || !user.errorLetters) return [];

        return Object.entries(user.errorLetters)
            .sort((a, b) => b[1] - a[1])
            .slice(0, limit)
            .map(([letter]) => letter);
    },

    /**
     * 设置当前用户
     */
    setCurrentUser(userId) {
        if (userId) {
            this.safeSetItem(this.KEYS.CURRENT_USER, userId);
        } else {
            this.safeRemoveItem(this.KEYS.CURRENT_USER);
        }
    },

    /**
     * 获取当前用户
     */
    getCurrentUser() {
        let userId = null;
        try {
            userId = localStorage.getItem(this.KEYS.CURRENT_USER);
        } catch {
            return null;
        }
        if (!userId) return null;

        const user = this.getUser(userId);
        if (!user) this.setCurrentUser(null);
        return user || null;
    },

    /**
     * 增加游戏计数（用于防沉迷）
     */
    incrementGameCount() {
        let count = this.getGameCount();
        count++;
        this.safeSetItem(this.KEYS.GAME_COUNT, count.toString());
        return count;
    },

    /**
     * 重置游戏计数
     */
    resetGameCount() {
        this.safeSetItem(this.KEYS.GAME_COUNT, '0');
    },

    /**
     * 获取游戏计数
     */
    getGameCount() {
        let rawCount = '0';
        try {
            rawCount = localStorage.getItem(this.KEYS.GAME_COUNT) || '0';
        } catch {
            rawCount = '0';
        }
        const count = Number.parseInt(rawCount, 10);
        return Number.isFinite(count) && count >= 0 ? count : 0;
    },

    /**
     * 保存设置
     */
    saveSettings(settings) {
        const nextSettings = {
            ...this.DEFAULT_SETTINGS,
            ...(settings || {})
        };
        this.safeSetItem(this.KEYS.SETTINGS, JSON.stringify(nextSettings));
        return nextSettings;
    },

    /**
     * 获取设置
     */
    getSettings() {
        return {
            ...this.DEFAULT_SETTINGS,
            ...this.readJson(this.KEYS.SETTINGS, {})
        };
    },

    readJson(key, fallback) {
        try {
            const data = localStorage.getItem(key);
            return data ? JSON.parse(data) : fallback;
        } catch {
            console.warn(`无法读取本地数据，已使用默认值: ${key}`);
            try {
                localStorage.removeItem(key);
            } catch {
                // 某些隐私模式下 localStorage 可能不可写，保持内存中的默认值即可。
            }
            return fallback;
        }
    },

    createId() {
        if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
        return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    },

    normalizeUser(user = {}) {
        const source = user && typeof user === 'object' ? user : {};
        return {
            id: String(source.id || this.createId()),
            name: String(source.name || '小玩家').trim().slice(0, 8),
            avatar: source.avatar || 'cat',
            totalScore: Math.min(this.MAX_SCORE, Math.max(0, Number(source.totalScore) || 0)),
            highScores: this.MODES.reduce((scores, mode) => {
                scores[mode] = Math.min(this.MAX_SCORE,
                    Math.max(0, Number(source.highScores?.[mode]) || 0));
                return scores;
            }, {}),
            badges: Array.isArray(source.badges) ? source.badges : [],
            errorLetters: this.normalizeErrorLetters(source.errorLetters),
            gamesPlayed: Math.max(0, Number(source.gamesPlayed) || 0),
            createdAt: source.createdAt || new Date().toISOString()
        };
    },

    normalizeErrorLetters(errorLetters) {
        if (!errorLetters || typeof errorLetters !== 'object' || Array.isArray(errorLetters)) {
            return {};
        }
        return Object.entries(errorLetters).reduce((result, [letter, count]) => {
            const normalizedLetter = String(letter).toUpperCase();
            const safeCount = Math.max(0, Math.floor(Number(count) || 0));
            if (/^[A-Z]$/.test(normalizedLetter) && safeCount > 0) {
                result[normalizedLetter] = safeCount;
            }
            return result;
        }, {});
    },

    safeSetItem(key, value) {
        try {
            localStorage.setItem(key, value);
            return true;
        } catch {
            console.warn(`无法写入本地数据: ${key}`);
            return false;
        }
    },

    safeRemoveItem(key) {
        try {
            localStorage.removeItem(key);
            return true;
        } catch {
            return false;
        }
    }
};


/* --- js/audio.js --- */
/* ===============================================
   音效管理
   =============================================== */




const Audio = {
    context: null,
    sounds: {},
    enabled: true,
    volume: 0.7,

    // 语音相关
    voices: [],
    preferredEnglishVoice: null,
    preferredChineseVoice: null,
    letterLanguage: 'zh',  // 'en' = 英文读音, 'zh' = 中文读音
    voicesLoaded: false,
    voicePlayer: null,
    voiceAssetBasePath: 'audio/voice/zh',
    voiceQueue: [],
    voiceQueuePlaying: false,
    voicePlaybackPrimed: false,
    voicePlaybackToken: 0,
    speechRequestId: 0,

    // 字母的汉语拼音发音映射
    letterPinyinSounds: LetterPinyinSounds,

    /**
     * 初始化音频上下文
     */
    init() {
        const settings = Storage.getSettings();
        this.enabled = settings.soundEnabled !== false;
        this.volume = Number.isFinite(Number(settings.volume))
            ? Math.max(0, Math.min(1, Number(settings.volume)))
            : 0.7;
        this.letterLanguage = settings.letterLanguage === 'zh' ? 'zh' : 'en';

        try {
            this.context = new (window.AudioContext || window.webkitAudioContext)();
        } catch (e) {
            console.warn('Web Audio API not supported');
        }

        // Web Audio 不可用时，语音播报仍然可以独立工作。
        this.initVoices();
    },

    /**
     * 初始化语音引擎列表
     */
    initVoices() {
        if (!('speechSynthesis' in window)) return;

        const loadVoices = () => {
            this.voices = speechSynthesis.getVoices();
            if (this.voices.length > 0) {
                this.voicesLoaded = true;
                this.selectPreferredVoices();
                console.log('语音引擎已加载，共', this.voices.length, '个');
            }
        };

        // 立即尝试加载
        loadVoices();

        // 监听 voiceschanged 事件（某些浏览器异步加载）
        speechSynthesis.onvoiceschanged = loadVoices;

        // iOS Safari 备用方案：延迟重试
        if (!this.voicesLoaded) {
            setTimeout(loadVoices, 100);
            setTimeout(loadVoices, 500);
            setTimeout(loadVoices, 1000);
        }
    },

    /**
     * 选择首选的语音引擎
     */
    selectPreferredVoices() {
        this.preferredEnglishVoice = null;
        this.preferredChineseVoice = null;

        // 美音引擎优先级列表
        const englishPreferences = [
            'Samantha',           // iOS/macOS 美音女声
            'Alex',              // macOS 美音男声
            'Google US English', // Chrome 美音
            'en-US',             // 通用美音标识
            'en_US'
        ];

        // 中文引擎优先级列表
        const chinesePreferences = [
            'Tingting',          // iOS/macOS 中文女声
            'Ting-Ting',         // 部分系统使用连字符名称
            'Xiaoxiao',          // Windows/Edge 自然中文女声
            'Yunyang',           // Windows/Edge 自然中文男声
            'Google 普通话',      // Chrome 中文
            'Meijia',            // 台湾中文女声
            'zh-CN',
            'zh_CN'
        ];

        // 选择英文语音
        for (const pref of englishPreferences) {
            const voice = this.voices.find(v =>
                v.name.includes(pref) || v.lang.includes(pref)
            );
            if (voice) {
                this.preferredEnglishVoice = voice;
                console.log('选择英文语音:', voice.name);
                break;
            }
        }

        // 如果没找到首选，使用任意英文语音
        if (!this.preferredEnglishVoice) {
            this.preferredEnglishVoice = this.voices.find(v =>
                v.lang.startsWith('en')
            );
        }

        // 选择中文语音
        for (const pref of chinesePreferences) {
            const voice = this.voices.find(v =>
                v.name.includes(pref) || v.lang.includes(pref)
            );
            if (voice) {
                this.preferredChineseVoice = voice;
                console.log('选择中文语音:', voice.name);
                break;
            }
        }

        // 如果没找到首选，使用任意中文语音
        if (!this.preferredChineseVoice) {
            this.preferredChineseVoice = this.voices.find(v =>
                v.lang.startsWith('zh')
            );
        }
    },

    /**
     * 生成稳定的本地语音资源键，避免在 file:// 页面中依赖 fetch。
     */
    hashText(text) {
        let hash = 2166136261;
        const value = String(text);

        for (let i = 0; i < value.length; i += 1) {
            hash ^= value.charCodeAt(i);
            hash = Math.imul(hash, 16777619);
        }

        return (hash >>> 0).toString(16);
    },

    /**
     * 获取内置中文语音资源路径。
     */
    getVoiceAssetPath(text) {
        return `${this.voiceAssetBasePath}/${this.hashText(text)}.wav`;
    },

    /**
     * 获取复用的 HTMLAudioElement。
     */
    getVoicePlayer() {
        if (!this.voicePlayer) {
            this.voicePlayer = new window.Audio();
        }
        return this.voicePlayer;
    },

    /**
     * 在用户点击“开始游戏”时提前解锁媒体播放，兼容 Safari 和 file:// 页面。
     * 音量设为 0，不会让用户听到额外的提示音。
     */
    primeVoicePlayback() {
        if (!this.enabled || this.voicePlaybackPrimed || !VoiceAssets.has(this.hashText('啊'))) {
            return;
        }

        const player = this.getVoicePlayer();
        const originalVolume = this.volume;
        const playbackToken = this.voicePlaybackToken;
        player.pause();
        player.currentTime = 0;
        player.volume = 0;
        player.onended = null;
        player.onerror = null;
        player.src = this.getVoiceAssetPath('啊');

        const playResult = player.play();
        const restore = () => {
            // 首条字母语音可能在预热音频尚未结束时生成；此时不能再暂停/重置
            // 同一个 Audio 元素，否则会把真实字母语音截断。
            if (playbackToken !== this.voicePlaybackToken) {
                this.voicePlaybackPrimed = true;
                return;
            }
            player.pause();
            player.currentTime = 0;
            player.volume = originalVolume;
            this.voicePlaybackPrimed = true;
        };

        if (playResult && typeof playResult.then === 'function') {
            playResult.then(restore).catch(() => {
                if (playbackToken === this.voicePlaybackToken) {
                    player.volume = originalVolume;
                }
                this.voicePlaybackPrimed = true;
            });
        } else {
            restore();
        }
    },

    /**
     * 取消当前本地语音及排队内容。
     */
    cancelVoicePlayback() {
        this.voicePlaybackToken += 1;
        this.voiceQueue = [];
        this.voiceQueuePlaying = false;

        if (this.voicePlayer) {
            this.voicePlayer.pause();
            this.voicePlayer.currentTime = 0;
            this.voicePlayer.onended = null;
            this.voicePlayer.onerror = null;
        }
    },

    /**
     * 播放队列中的下一条本地语音。
     */
    drainVoiceQueue() {
        if (this.voiceQueuePlaying || this.voiceQueue.length === 0) return;

        const nextVoice = this.voiceQueue.shift();
        this.voiceQueuePlaying = true;
        const playbackToken = this.voicePlaybackToken;
        const player = this.getVoicePlayer();
        let settled = false;

        const finish = () => {
            if (settled || playbackToken !== this.voicePlaybackToken) return;
            settled = true;
            this.voiceQueuePlaying = false;
            player.onended = null;
            player.onerror = null;
            this.drainVoiceQueue();
        };

        const fallback = () => {
            if (playbackToken !== this.voicePlaybackToken) return;
            if (typeof nextVoice.fallback === 'function') nextVoice.fallback();
            finish();
        };

        player.pause();
        player.currentTime = 0;
        player.volume = this.volume;
        player.onended = finish;
        player.onerror = fallback;
        player.src = this.getVoiceAssetPath(nextVoice.text);

        try {
            const playResult = player.play();
            if (playResult && typeof playResult.catch === 'function') {
                playResult.catch(fallback);
            }
        } catch {
            // 某些浏览器会同步抛出 NotAllowedError，必须立即走系统语音兜底，
            // 否则 voiceQueuePlaying 会一直保持 true，后续字母全部无声。
            fallback();
        }
    },

    /**
     * 播放内置语音；资源不存在或浏览器拒绝播放时由调用方回退到系统语音。
     * interrupt=false 时进入本地队列，保证拼音分步朗读不会互相截断。
     */
    playChineseAsset(text, fallback, { interrupt = true } = {}) {
        if (!this.enabled || !VoiceAssets.has(this.hashText(text))) {
            return false;
        }

        if (interrupt) {
            this.cancelVoicePlayback();
        }

        this.voiceQueue.push({ text, fallback });
        this.drainVoiceQueue();
        return true;
    },

    /**
     * 生成简单音效
     */
    playTone(frequency, duration, type = 'sine') {
        if (!this.enabled || !this.context) return;

        try {
            const oscillator = this.context.createOscillator();
            const gainNode = this.context.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(this.context.destination);

            oscillator.type = type;
            oscillator.frequency.setValueAtTime(frequency, this.context.currentTime);

            gainNode.gain.setValueAtTime(this.volume * 0.3, this.context.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.01, this.context.currentTime + duration);

            oscillator.start(this.context.currentTime);
            oscillator.stop(this.context.currentTime + duration);
        } catch (e) {
            console.warn('Audio play failed:', e);
        }
    },

    /**
     * 播放正确音效 - 欢快的"叮"声
     */
    playCorrect() {
        if (!this.enabled || !this.context) return;

        // 播放两个音符形成和弦
        this.playTone(523.25, 0.15, 'sine');  // C5
        setTimeout(() => this.playTone(659.25, 0.2, 'sine'), 50);  // E5
        setTimeout(() => this.playTone(783.99, 0.25, 'sine'), 100);  // G5
    },

    /**
     * 播放错误音效 - 低沉的"嘟"声
     */
    playWrong() {
        if (!this.enabled || !this.context) return;

        this.playTone(200, 0.15, 'square');
        setTimeout(() => this.playTone(150, 0.2, 'square'), 100);
    },

    /**
     * 播放按键音效
     */
    playKeyPress() {
        if (!this.enabled || !this.context) return;

        this.playTone(440, 0.05, 'sine');
    },

    /**
     * 播放倒计时警告音
     */
    playTimerWarning() {
        if (!this.enabled || !this.context) return;

        this.playTone(880, 0.1, 'sine');
    },

    /**
     * 播放游戏结束音效
     */
    playGameOver() {
        if (!this.enabled || !this.context) return;

        // 播放下降音阶
        const notes = [523.25, 493.88, 440, 392];
        notes.forEach((freq, i) => {
            setTimeout(() => this.playTone(freq, 0.3, 'sine'), i * 150);
        });
    },

    /**
     * 播放胜利音效
     */
    playVictory() {
        if (!this.enabled || !this.context) return;

        // 播放欢快的上升音阶
        const notes = [392, 440, 493.88, 523.25, 587.33, 659.25];
        notes.forEach((freq, i) => {
            setTimeout(() => this.playTone(freq, 0.15, 'sine'), i * 80);
        });
    },

    /**
     * 播放新勋章音效
     */
    playBadgeUnlock() {
        if (!this.enabled || !this.context) return;

        // 华丽的音效
        setTimeout(() => this.playTone(523.25, 0.2, 'sine'), 0);
        setTimeout(() => this.playTone(659.25, 0.2, 'sine'), 150);
        setTimeout(() => this.playTone(783.99, 0.2, 'sine'), 300);
        setTimeout(() => this.playTone(1046.5, 0.4, 'sine'), 450);
    },

    /**
     * 使用 Web Speech API 朗读文本
     * @param {string} text 要朗读的文本
     * @param {string} lang 语言代码
     * @param {SpeechSynthesisVoice} preferredVoice 首选语音引擎
     */
    speak(text, lang = 'zh-CN', preferredVoice = null, { interrupt = true } = {}) {
        if (!this.enabled) return;

        const requestId = ++this.speechRequestId;
        if (interrupt) this.cancelVoicePlayback();

        const speech = globalThis.window?.speechSynthesis;
        const Utterance = globalThis.window?.SpeechSynthesisUtterance
            || globalThis.SpeechSynthesisUtterance;
        if (speech && typeof Utterance === 'function') {
            if (interrupt) {
                speech.cancel();
                speech.resume?.();
            }

            const utterance = new Utterance(text);
            utterance.lang = lang;
            utterance.rate = 0.82; // 放慢语速，给儿童留出辨音时间
            utterance.pitch = 1.0; // 使用自然音高，减少机械感
            utterance.volume = this.volume;

            // 使用首选语音引擎
            if (preferredVoice) {
                utterance.voice = preferredVoice;
            }

            const speakNow = () => {
                if (interrupt && requestId !== this.speechRequestId) return;
                speech.resume?.();
                speech.speak(utterance);
            };

            // cancel() 后部分 Safari/Chrome 需要一次事件循环再 speak，
            // 否则切换到英文时会出现“按钮有反馈但没有声音”。
            if (interrupt) {
                setTimeout(speakNow, 30);
            } else {
                speakNow();
            }
        }
    },

    /**
     * 朗读字母（根据当前语言设置）
     */
    speakLetter(letter) {
        const upperLetter = String(letter ?? '').toUpperCase();
        if (!upperLetter) return;

        if (this.letterLanguage === 'zh') {
            // 中文模式：读字母的汉语拼音发音（如 A 读 "啊"）
            const pinyinSound = this.letterPinyinSounds[upperLetter] || upperLetter;
            const speakFallback = () => this.speak(
                pinyinSound,
                'zh-CN',
                this.preferredChineseVoice
            );

            if (!this.playChineseAsset(pinyinSound, speakFallback)) {
                speakFallback();
            }
        } else {
            // 英文模式使用可读的单词，避免部分系统将 "A." 当作标点而不发音。
            const englishSounds = {
                A: 'ay', B: 'bee', C: 'see', D: 'dee', E: 'ee', F: 'ef',
                G: 'gee', H: 'aitch', I: 'eye', J: 'jay', K: 'kay', L: 'el',
                M: 'em', N: 'en', O: 'oh', P: 'pee', Q: 'cue', R: 'ar',
                S: 'ess', T: 'tee', U: 'you', V: 'vee', W: 'double you',
                X: 'ex', Y: 'why', Z: 'zee'
            };
            const phoneticText = englishSounds[upperLetter] || upperLetter;
            this.speak(phoneticText, 'en-US', this.preferredEnglishVoice);
        }
    },

    /**
     * 朗读拼音（使用中文发音）
     * 为了确保语音引擎用中文读拼音而不是英文，
     * 我们使用拼音对应的汉字发音
     */
    speakPinyin(pinyin, options = {}) {
        const sourceText = String(pinyin ?? '');
        const lowerPinyin = sourceText.toLowerCase();
        const speechText = PinyinSpeechMap[lowerPinyin] || sourceText;
        const speakFallback = () => this.speak(
            speechText,
            'zh-CN',
            this.preferredChineseVoice,
            options
        );

        if (!this.playChineseAsset(speechText, speakFallback, options)) {
            speakFallback();
        }
    },

    /**
     * 朗读引导语
     */
    speakGuide(text) {
        const speakFallback = () => this.speak(text, 'zh-CN', this.preferredChineseVoice);

        if (!this.playChineseAsset(text, speakFallback)) {
            speakFallback();
        }
    },

    /**
     * 停止当前语音，离开游戏或切换关卡时调用。
     */
    stopSpeaking() {
        this.speechRequestId += 1;
        this.cancelVoicePlayback();
        const speech = globalThis.window?.speechSynthesis;
        if (speech) speech.cancel();
    },

    /**
     * 设置字母读音语言
     * @param {string} lang 'en' = 英文, 'zh' = 中文
     */
    setLetterLanguage(lang) {
        this.letterLanguage = lang === 'zh' ? 'zh' : 'en';
        Storage.saveSettings({ ...Storage.getSettings(), letterLanguage: this.letterLanguage });
    },

    /**
     * 获取当前字母读音语言
     */
    getLetterLanguage() {
        return this.letterLanguage;
    },

    /**
     * 切换字母读音语言
     */
    toggleLetterLanguage() {
        const newLang = this.letterLanguage === 'en' ? 'zh' : 'en';
        this.setLetterLanguage(newLang);
        return newLang;
    },

    /**
     * 设置音效开关
     */
    setEnabled(enabled) {
        this.enabled = enabled;
        Storage.saveSettings({ ...Storage.getSettings(), soundEnabled: enabled });
    },

    /**
     * 设置音量
     */
    setVolume(volume) {
        this.volume = Math.max(0, Math.min(1, volume));
        Storage.saveSettings({ ...Storage.getSettings(), volume: this.volume });
    },

    /**
     * 恢复音频上下文（需要用户交互后调用）
     */
    resume() {
        if (this.context && this.context.state === 'suspended') {
            this.context.resume();
        }
    }
};


/* --- js/keyboard.js --- */
/* ===============================================
   虚拟键盘控制
   =============================================== */


const Keyboard = {
    container: null,
    keys: {},
    currentHighlight: null,
    onKeyPress: null,  // 按键回调

    // 键盘布局
    layout: [
        ['Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P'],
        ['A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L'],
        ['Z', 'X', 'C', 'V', 'B', 'N', 'M']
    ],

    // 左手区按键
    leftHandKeys: ['Q', 'W', 'E', 'R', 'T', 'A', 'S', 'D', 'F', 'G', 'Z', 'X', 'C', 'V', 'B'],

    // 手指指法映射（对应 HTML data-finger 属性）
    fingerGuide: {
        'Q': 'left-pinky', 'A': 'left-pinky', 'Z': 'left-pinky',
        'W': 'left-ring', 'S': 'left-ring', 'X': 'left-ring',
        'E': 'left-middle', 'D': 'left-middle', 'C': 'left-middle',
        'R': 'left-index', 'F': 'left-index', 'V': 'left-index',
        'T': 'left-index', 'G': 'left-index', 'B': 'left-index',
        'Y': 'right-index', 'H': 'right-index', 'N': 'right-index',
        'U': 'right-index', 'J': 'right-index', 'M': 'right-index',
        'I': 'right-middle', 'K': 'right-middle',
        'O': 'right-ring', 'L': 'right-ring',
        'P': 'right-pinky'
    },

    // 虚拟手元素
    leftHand: null,
    rightHand: null,
    eventsBound: false,

    /**
     * 初始化键盘
     */
    init(containerId) {
        this.container = document.getElementById(containerId);
        // 不再需要获取整个 leftHand/rightHand，我们需要操作具体的 finger
        this.render();
        this.bindEvents();
    },

    /**
     * 渲染键盘
     */
    render() {
        if (!this.container) return;

        this.container.innerHTML = '';
        this.keys = {};

        this.layout.forEach((row, rowIndex) => {
            const rowDiv = document.createElement('div');
            rowDiv.className = 'keyboard-row';

            row.forEach(key => {
                const keyBtn = document.createElement('button');
                keyBtn.className = 'key';
                keyBtn.dataset.key = key;
                keyBtn.textContent = key;

                // 添加左右手区分
                if (this.leftHandKeys.includes(key)) {
                    keyBtn.classList.add('left-hand');
                } else {
                    keyBtn.classList.add('right-hand');
                }

                // 添加手指指引
                const fingerGuide = document.createElement('span');
                fingerGuide.className = 'finger-guide';
                fingerGuide.textContent = this.fingerGuide[key];
                keyBtn.appendChild(fingerGuide);

                rowDiv.appendChild(keyBtn);
                this.keys[key] = keyBtn;
            });

            this.container.appendChild(rowDiv);
        });
    },

    /**
     * 绑定事件
     */
    bindEvents() {
        if (!this.container || this.eventsBound) return;
        this.eventsBound = true;

        // 物理键盘事件
        document.addEventListener('keydown', (e) => {
            if (e.repeat) return;
            const key = e.key.toUpperCase();
            if (this.keys[key]) {
                e.preventDefault();
                this.handleKeyPress(key);
            }
        });

        document.addEventListener('keyup', (e) => {
            const key = e.key.toUpperCase();
            if (this.keys[key]) {
                this.keys[key].classList.remove('pressed');
            }
        });

        // 虚拟键盘点击事件
        this.container.addEventListener('click', (e) => {
            const keyBtn = e.target.closest('.key');
            if (keyBtn) {
                const key = keyBtn.dataset.key;
                this.handleKeyPress(key);
            }
        });

        // 触摸事件（移动端优化）
        this.container.addEventListener('touchstart', (e) => {
            const keyBtn = e.target.closest('.key');
            if (keyBtn) {
                keyBtn.classList.add('pressed');
            }
        }, { passive: true });

        this.container.addEventListener('touchend', (e) => {
            const keyBtn = e.target.closest('.key');
            if (keyBtn) {
                keyBtn.classList.remove('pressed');
            }
        }, { passive: true });
    },

    /**
     * 处理按键
     */
    handleKeyPress(key) {
        const normalizedKey = String(key ?? '').toUpperCase() === 'Ü'
            ? 'V'
            : String(key ?? '').toUpperCase();
        const keyBtn = this.keys[normalizedKey];
        if (!keyBtn) return;

        // 添加按下效果
        keyBtn.classList.add('pressed');
        setTimeout(() => keyBtn.classList.remove('pressed'), 100);

        // 播放按键音
        Audio.playKeyPress();

        // 调用回调
        if (this.onKeyPress) {
            this.onKeyPress(normalizedKey);
        }
    },

    /**
     * 高亮按键并显示手指引导
     */
    highlight(key) {
        // 移除之前的高亮
        this.clearHighlight();

        const keyBtn = this.keys[key.toUpperCase()];
        if (keyBtn) {
            keyBtn.classList.add('highlight');
            this.currentHighlight = key.toUpperCase();

            // 显示手指引导
            this.showFingerGuide(key.toUpperCase());
        }
    },

    /**
     * 显示手指引导 - 高亮对应 CSS 手指
     */
    showFingerGuide(key) {
        const fingerId = this.fingerGuide[key];
        if (!fingerId) return;

        // 清除所有手指高亮
        document.querySelectorAll('.css-finger').forEach(el => {
            el.classList.remove('active', 'pressing', 'success');
        });

        // 找到对应的 CSS 手指元素
        const cssFinger = document.querySelector(`.css-finger[data-finger="${fingerId}"]`);
        if (cssFinger) {
            cssFinger.classList.add('active');
        }
    },

    /**
     * 清除高亮和手指引导
     */
    clearHighlight() {
        if (this.currentHighlight && this.keys[this.currentHighlight]) {
            this.keys[this.currentHighlight].classList.remove('highlight');
        }
        this.currentHighlight = null;

        // 清除所有手指高亮
        document.querySelectorAll('.css-finger').forEach(el => {
            el.classList.remove('active', 'pressing', 'success');
        });
    },

    /**
     * 显示正确反馈
     */
    showCorrect(key) {
        const keyBtn = this.keys[key.toUpperCase()];
        if (keyBtn) {
            keyBtn.classList.remove('highlight');
            keyBtn.classList.add('correct');
            setTimeout(() => keyBtn.classList.remove('correct'), 500);
        }

        // CSS 手指按压动画
        const fingerId = this.fingerGuide[key.toUpperCase()];
        if (fingerId) {
            const cssFinger = document.querySelector(`.css-finger[data-finger="${fingerId}"]`);
            if (cssFinger) {
                // 移除 active，添加 pressing
                cssFinger.classList.remove('active');
                cssFinger.classList.add('pressing');

                // 播放完按下动画后显示成功色
                setTimeout(() => {
                    cssFinger.classList.remove('pressing');
                    cssFinger.classList.add('success');
                }, 100);

                // 最后清除
                setTimeout(() => {
                    cssFinger.classList.remove('success');
                }, 600);
            }
        }
    },

    /**
     * 显示错误反馈
     */
    showWrong(key) {
        const keyBtn = this.keys[key.toUpperCase()];
        if (keyBtn) {
            keyBtn.classList.add('wrong');
            setTimeout(() => keyBtn.classList.remove('wrong'), 500);
        }
    },

    /**
     * 设置按键回调
     */
    setKeyPressCallback(callback) {
        this.onKeyPress = callback;
    },

    /**
     * 重置键盘状态
     */
    reset() {
        this.clearHighlight();
        Object.values(this.keys).forEach(keyBtn => {
            keyBtn.classList.remove('correct', 'wrong', 'pressed');
        });
    },

    /**
     * 获取所有字母
     */
    getAllLetters() {
        return this.layout.flat();
    },

    /**
     * 显示/隐藏键盘
     */
    show() {
        const container = document.getElementById('keyboard-container');
        if (container) container.style.display = 'block';
    },

    hide() {
        const container = document.getElementById('keyboard-container');
        if (container) container.style.display = 'none';
    }
};


/* --- js/letters.js --- */
/* ===============================================
   字母森林 - 字母掉落游戏逻辑
   =============================================== */





const LettersGame = {
    canvas: null,
    ctx: null,
    fallingLetters: [],
    animationId: null,
    spawnTimer: null,
    spawnTimeout: null,
    isRunning: false,

    // 游戏配置
    config: {
        baseSpawnInterval: 2000, // 基准生成间隔
        spawnInterval: 4000,      // 当前生成间隔（默认 0.5x）
        baseFallSpeed: 1.5,      // 基准下落速度
        fallSpeed: 0.75,          // 当前下落速度（默认 0.5x）
        letterSize: 60,           // 字母大小
        maxLetters: 5,            // 同时存在的最大字母数
        frequentErrorBoost: 0.3   // 易错字母出现概率提升
    },

    speedFactor: 0.5,

    // 回调函数
    onCorrect: null,
    onWrong: null,
    onMiss: null,

    /**
     * 初始化游戏
     */
    init(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.resize();

        // 监听窗口大小变化
        window.addEventListener('resize', () => this.resize());
    },

    /**
     * 设置游戏速度
     * @param {number} factor 速度倍率 (0.5 - 2.0)
     */
    setSpeed(factor) {
        const oldFactor = this.speedFactor || 1.0;
        this.speedFactor = factor;

        // 更新配置
        this.config.spawnInterval = this.config.baseSpawnInterval / factor;
        this.config.fallSpeed = this.config.baseFallSpeed * factor;

        // 更新现有字母的速度
        this.fallingLetters.forEach(letter => {
            letter.speed = letter.speed * (factor / oldFactor);
        });

        // 如果正在运行，重启生成定时器
        if (this.isRunning && this.spawnTimer) this.startSpawnTimer();
    },

    /**
     * 调整画布大小
     */
    resize() {
        if (!this.canvas) return;

        const container = this.canvas.parentElement;
        this.canvas.width = container.clientWidth;
        this.canvas.height = container.clientHeight;
    },

    /**
     * 开始游戏
     */
    start() {
        this.clearTimers();
        if (this.animationId) cancelAnimationFrame(this.animationId);

        this.isRunning = true;
        this.fallingLetters = [];

        // 在下一帧调整大小，确保 DOM 已经渲染
        requestAnimationFrame(() => {
            if (!this.isRunning) return;
            this.resize();

            // 延迟生成第一个字母，让用户有准备时间
            this.spawnTimeout = setTimeout(() => {
                this.spawnTimeout = null;
                if (!this.isRunning) return;
                // 开始生成字母
                this.spawnLetter();
                this.startSpawnTimer();
            }, 1500);

            // 开始动画循环
            this.animate();

            // 设置键盘回调
            Keyboard.setKeyPressCallback((key) => this.handleKeyPress(key));
        });
    },

    /**
     * 停止游戏
     */
    stop() {
        this.isRunning = false;
        this.clearTimers();

        if (this.animationId) {
            cancelAnimationFrame(this.animationId);
            this.animationId = null;
        }

        Keyboard.setKeyPressCallback(null);
        Keyboard.reset();
        this.fallingLetters = [];
    },

    /**
     * 暂停游戏
     */
    pause() {
        if (!this.isRunning) return;
        this.isRunning = false;
        this.clearTimers();
        if (this.animationId) {
            cancelAnimationFrame(this.animationId);
            this.animationId = null;
        }
    },

    /**
     * 继续游戏
     */
    resume() {
        if (this.isRunning) return;
        this.isRunning = true;
        this.startSpawnTimer();
        this.animate();
    },

    /**
     * 生成一个掉落的字母
     */
    spawnLetter() {
        if (!this.isRunning || !this.canvas) return;
        const allLetters = Keyboard.getAllLetters();
        if (allLetters.length === 0) return;
        let letter;

        // 获取用户容易错的字母，提高它们的出现概率
        const currentUser = Storage.getCurrentUser();
        const frequentErrors = currentUser ? Storage.getFrequentErrors(currentUser.id) : [];

        if (frequentErrors.length > 0 && Math.random() < this.config.frequentErrorBoost) {
            letter = Utils.randomChoice(frequentErrors);
        } else {
            letter = Utils.randomChoice(allLetters);
        }

        const minX = Math.min(80, Math.max(0, this.canvas.width / 2));
        const maxX = Math.max(minX, this.canvas.width - 80);
        const x = Utils.randomInt(minX, maxX);

        this.fallingLetters.push({
            letter,
            x,
            y: -this.config.letterSize,
            speed: this.config.fallSpeed + Math.random() * 0.5,
            size: this.config.letterSize,
            rotation: 0,
            rotationSpeed: (Math.random() - 0.5) * 0.05,
            color: this.getLetterColor(letter),
            collected: false
        });

        // 高亮对应的键盘按键
        this.updateHighlight();

        // 朗读字母，起引导作用
        Audio.speakLetter(letter);
    },

    /**
     * 获取字母颜色（区分左右手）
     */
    getLetterColor(letter) {
        if (Keyboard.leftHandKeys.includes(letter)) {
            return '#64B5F6';  // 左手蓝色
        }
        return '#FFB74D';  // 右手橙色
    },

    /**
     * 更新键盘高亮
     */
    updateHighlight() {
        // 高亮最低位置的字母
        const lowestLetter = this.fallingLetters
            .filter(l => !l.collected)
            .sort((a, b) => b.y - a.y)[0];

        if (lowestLetter) {
            Keyboard.highlight(lowestLetter.letter);
        } else {
            Keyboard.clearHighlight();
        }
    },

    /**
     * 处理按键
     */
    handleKeyPress(key) {
        if (!this.isRunning) return;

        // 查找匹配的字母（优先匹配位置最低的）
        const matchingLetter = this.fallingLetters
            .filter(l => !l.collected && l.letter === key)
            .sort((a, b) => b.y - a.y)[0];

        if (matchingLetter) {
            // 正确！
            matchingLetter.collected = true;

            // 视觉反馈
            Keyboard.showCorrect(key);
            Audio.playCorrect();

            // 粒子效果
            const rect = this.canvas.getBoundingClientRect();
            Utils.createParticles(
                rect.left + matchingLetter.x,
                rect.top + matchingLetter.y,
                8,
                document.body
            );

            // 得分动画
            Utils.createScorePopup(
                matchingLetter.x,
                matchingLetter.y,
                10,
                this.canvas.parentElement
            );

            // 回调
            if (this.onCorrect) {
                this.onCorrect(key, matchingLetter.x, matchingLetter.y);
            }

            this.updateHighlight();
        } else {
            // 错误！
            Keyboard.showWrong(key);
            Audio.playWrong();
            Utils.vibrate(100);

            if (this.onWrong) {
                this.onWrong(key);
            }
        }
    },

    /**
     * 动画循环
     */
    animate() {
        if (!this.isRunning) return;

        this.update();
        this.draw();

        this.animationId = requestAnimationFrame(() => this.animate());
    },

    /**
     * 更新游戏状态
     */
    update() {
        const groundY = this.canvas.height - 100;  // 键盘区域上方

        this.fallingLetters = this.fallingLetters.filter(letter => {
            if (letter.collected) {
                return false;  // 移除已收集的字母
            }

            // 更新位置
            letter.y += letter.speed;
            letter.rotation += letter.rotationSpeed;

            // 检查是否掉到底部
            if (letter.y > groundY) {
                // 错过了！
                if (this.onMiss) {
                    this.onMiss(letter.letter);
                }
                Audio.playWrong();
                return false;  // 移除
            }

            return true;
        });

        this.updateHighlight();
    },

    /**
     * 绘制游戏画面
     */
    draw() {
        // 清空画布
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        // 绘制背景装饰（树木等）
        this.drawBackground();

        // 绘制掉落的字母（苹果形状）
        this.fallingLetters.forEach(letter => {
            if (!letter.collected) {
                this.drawApple(letter);
            }
        });
    },

    /**
     * 绘制背景
     */
    drawBackground() {
        const ctx = this.ctx;

        // 绘制一些简单的云朵
        ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
        this.drawCloud(100, 60, 60);
        this.drawCloud(300, 100, 45);
        this.drawCloud(500, 50, 50);
        this.drawCloud(700, 80, 55);
    },

    /**
     * 绘制云朵
     */
    drawCloud(x, y, size) {
        const ctx = this.ctx;
        ctx.beginPath();
        ctx.arc(x, y, size * 0.5, 0, Math.PI * 2);
        ctx.arc(x + size * 0.4, y - size * 0.1, size * 0.4, 0, Math.PI * 2);
        ctx.arc(x + size * 0.8, y, size * 0.45, 0, Math.PI * 2);
        ctx.fill();
    },

    /**
     * 绘制苹果形状的字母
     */
    drawApple(letter) {
        const ctx = this.ctx;
        const { x, y, size, rotation, color } = letter;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(rotation);

        // 苹果身体
        const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, size * 0.5);
        gradient.addColorStop(0, '#FF6B6B');
        gradient.addColorStop(0.7, '#E53935');
        gradient.addColorStop(1, '#C62828');

        ctx.beginPath();
        ctx.arc(0, 0, size * 0.45, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();

        // 苹果梗
        ctx.beginPath();
        ctx.moveTo(0, -size * 0.4);
        ctx.quadraticCurveTo(5, -size * 0.55, 0, -size * 0.6);
        ctx.strokeStyle = '#5D4037';
        ctx.lineWidth = 4;
        ctx.stroke();

        // 叶子
        ctx.beginPath();
        ctx.ellipse(size * 0.15, -size * 0.5, size * 0.12, size * 0.06, Math.PI / 4, 0, Math.PI * 2);
        ctx.fillStyle = '#4CAF50';
        ctx.fill();

        // 高光
        ctx.beginPath();
        ctx.arc(-size * 0.15, -size * 0.15, size * 0.12, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.fill();

        // 字母
        ctx.fillStyle = '#FFFFFF';
        ctx.font = `bold ${size * 0.5}px "Noto Sans SC", sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(letter.letter, 0, 5);

        // 字母阴影
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.3)';
        ctx.lineWidth = 2;
        ctx.strokeText(letter.letter, 0, 5);

        ctx.restore();
    },

    /**
     * 设置游戏配置
     */
    setConfig(config) {
        this.config = { ...this.config, ...config };
    },

    /**
     * 设置回调函数
     */
    setCallbacks({ onCorrect, onWrong, onMiss }) {
        this.onCorrect = onCorrect || null;
        this.onWrong = onWrong || null;
        this.onMiss = onMiss || null;
    },

    clearTimers() {
        if (this.spawnTimer) {
            clearInterval(this.spawnTimer);
            this.spawnTimer = null;
        }
        if (this.spawnTimeout) {
            clearTimeout(this.spawnTimeout);
            this.spawnTimeout = null;
        }
    },

    startSpawnTimer() {
        this.clearTimers();
        if (!this.isRunning) return;

        this.spawnTimer = setInterval(() => {
            if (this.fallingLetters.length < this.config.maxLetters) {
                this.spawnLetter();
            }
        }, this.config.spawnInterval);
    }
};


/* --- js/pinyin.js --- */
/* ===============================================
   拼音合成室游戏逻辑
   =============================================== */





const PinyinGame = {
    currentPinyin: null,
    inputBuffer: '',
    inputIndex: 0,
    isRunning: false,
    pendingTimers: new Set(),

    // 回调函数
    onCorrect: null,
    onWrong: null,

    // DOM 元素
    elements: {
        shengmu: null,
        yunmu: null,
        result: null
    },

    /**
     * 初始化
     */
    init() {
        this.elements.shengmu = document.getElementById('shengmu');
        this.elements.yunmu = document.getElementById('yunmu');
        this.elements.result = document.getElementById('pinyin-result');
    },

    /**
     * 开始游戏
     */
    start() {
        this.clearTimers();
        this.isRunning = true;
        this.inputBuffer = '';
        this.inputIndex = 0;
        this.currentPinyin = null;

        // 设置键盘回调
        Keyboard.setKeyPressCallback((key) => this.handleKeyPress(key));

        // 延迟生成第一个拼音，让用户有准备时间
        this.schedule(() => {
            if (this.isRunning) this.nextPinyin();
        }, 1500);
    },

    /**
     * 停止游戏
     */
    stop() {
        this.isRunning = false;
        this.clearTimers();
        this.currentPinyin = null;
        Keyboard.setKeyPressCallback(null);
        Keyboard.reset();
        Audio.stopSpeaking();
    },

    /**
     * 暂停
     */
    pause() {
        this.isRunning = false;
        this.clearTimers();
        Audio.stopSpeaking();
    },

    /**
     * 继续
     */
    resume() {
        this.isRunning = true;
        if (!this.currentPinyin || this.isCurrentComplete()) {
            this.schedule(() => {
                if (this.isRunning) this.nextPinyin();
            }, 0);
        }
    },

    /**
     * 生成下一个拼音
     */
    nextPinyin() {
        // 从拼音数据中随机选择
        const pinyin = Utils.randomChoice(PinyinData.combinations);
        if (!pinyin) return;
        this.currentPinyin = pinyin;
        this.inputBuffer = '';
        this.inputIndex = 0;

        // 更新显示
        this.elements.shengmu.textContent = pinyin.shengmu;
        this.elements.yunmu.textContent = pinyin.yunmu;
        this.elements.result.textContent = '?';

        // 高亮第一个字母
        const fullPinyin = Utils.normalizePinyinInput(pinyin.shengmu + pinyin.yunmu);
        if (fullPinyin.length > 0) {
            Keyboard.highlight(fullPinyin[0]);
        }

        // 朗读完整拼音引导（中文拼音发音）
        this.schedule(() => {
            if (!this.isRunning) return;
            // 朗读完整拼音组合
            Audio.speakPinyin(pinyin.shengmu + pinyin.yunmu);
        }, 300);
    },

    /**
     * 处理按键
     */
    handleKeyPress(key) {
        if (!this.isRunning || !this.currentPinyin) return;

        const fullPinyin = Utils.normalizePinyinInput(
            this.currentPinyin.shengmu + this.currentPinyin.yunmu
        );
        const expectedKey = fullPinyin[this.inputIndex];

        if (key === expectedKey) {
            // 正确
            this.inputBuffer += key.toLowerCase();
            this.inputIndex++;

            Keyboard.showCorrect(key);
            Audio.playCorrect();

            // 检查是否完成
            if (this.inputIndex >= fullPinyin.length) {
                // 完成拼音
                this.completePinyin();
            } else {
                // 高亮下一个字母
                Keyboard.highlight(fullPinyin[this.inputIndex]);
            }
        } else {
            // 错误
            Keyboard.showWrong(key);
            Audio.playWrong();

            if (this.onWrong) {
                this.onWrong();
            }
        }
    },

    /**
     * 完成拼音
     */
    completePinyin() {
        const pinyin = this.currentPinyin;
        const fullPinyin = Utils.normalizePinyinInput(pinyin.shengmu + pinyin.yunmu);

        // 显示结果
        this.elements.result.textContent = fullPinyin;
        this.elements.result.style.animation = 'scaleBounce 0.5s ease';

        // 朗读完整拼音（分步朗读：声母 -> 韵母 -> 完整拼音）
        this.schedule(() => {
            if (!this.isRunning) return;
            // 先读声母（如果有的话）
            if (pinyin.shengmu) {
                Audio.speakPinyin(pinyin.shengmu, { interrupt: true });
            }

            // 再读韵母
            this.schedule(() => {
                if (!this.isRunning) return;
                Audio.speakPinyin(pinyin.yunmu, { interrupt: false });

                // 最后读完整拼音
                this.schedule(() => {
                    if (!this.isRunning) return;
                    Audio.speakPinyin(pinyin.shengmu + pinyin.yunmu, { interrupt: false });

                    // 如果有例字，朗读例字
                    if (pinyin.example) {
                        this.schedule(() => {
                            if (this.isRunning) Audio.speakPinyin(pinyin.example, { interrupt: false });
                        }, 800);
                    }
                }, 600);
            }, 600);
        }, 300);

        // 回调
        if (this.onCorrect) {
            this.onCorrect();
        }

        // 粒子效果
        Utils.createParticles(
            window.innerWidth / 2,
            window.innerHeight / 2,
            12,
            document.body
        );

        // 下一个拼音
        this.schedule(() => {
            if (this.isRunning) {
                this.elements.result.style.animation = '';
                this.nextPinyin();
            }
        }, 3500);
    },

    /**
     * 设置回调
     */
    setCallbacks({ onCorrect, onWrong }) {
        this.onCorrect = onCorrect || null;
        this.onWrong = onWrong || null;
    },

    isCurrentComplete() {
        if (!this.currentPinyin) return false;
        const fullPinyin = Utils.normalizePinyinInput(
            this.currentPinyin.shengmu + this.currentPinyin.yunmu
        );
        return this.inputIndex >= fullPinyin.length;
    },

    schedule(callback, delay) {
        const timer = setTimeout(() => {
            this.pendingTimers.delete(timer);
            callback();
        }, delay);
        this.pendingTimers.add(timer);
        return timer;
    },

    clearTimers() {
        this.pendingTimers.forEach(timer => clearTimeout(timer));
        this.pendingTimers.clear();
    }
};


/* --- js/words.js --- */
/* ===============================================
   词语竞速游戏逻辑
   =============================================== */





const WordsGame = {
    currentWord: null,
    currentPinyin: '',
    inputBuffer: '',
    inputIndex: 0,
    isRunning: false,
    pendingTimers: new Set(),
    showHint: true,  // 是否显示拼音提示
    grade: 1,        // 年级

    // 回调函数
    onCorrect: null,
    onWrong: null,

    // DOM 元素
    elements: {
        hanzi: null,
        pinyinHint: null,
        inputDisplay: null
    },

    /**
     * 初始化
     */
    init() {
        this.elements.hanzi = document.getElementById('hanzi');
        this.elements.pinyinHint = document.getElementById('pinyin-hint');
        this.elements.inputDisplay = document.getElementById('input-display');
    },

    /**
     * 开始游戏
     */
    start(options = {}) {
        this.clearTimers();
        this.isRunning = true;
        this.inputBuffer = '';
        this.inputIndex = 0;
        this.showHint = options.showHint !== false;
        this.grade = options.grade || 1;

        // 生成第一个词语
        this.nextWord();

        // 设置键盘回调
        Keyboard.setKeyPressCallback((key) => this.handleKeyPress(key));
    },

    /**
     * 停止游戏
     */
    stop() {
        this.isRunning = false;
        this.clearTimers();
        this.currentWord = null;
        Keyboard.setKeyPressCallback(null);
        Keyboard.reset();
        Audio.stopSpeaking();
    },

    /**
     * 暂停
     */
    pause() {
        this.isRunning = false;
        this.clearTimers();
        Audio.stopSpeaking();
    },

    /**
     * 继续
     */
    resume() {
        this.isRunning = true;
        if (!this.currentWord || this.isCurrentComplete()) {
            this.schedule(() => {
                if (this.isRunning) this.nextWord();
            }, 0);
        }
    },

    /**
     * 获取当前年级的词库
     */
    getWordList() {
        if (!WordsData || !WordsData.grades) {
            return [];
        }
        return WordsData.grades[this.grade] || WordsData.grades[1] || [];
    },

    /**
     * 生成下一个词语
     */
    nextWord() {
        const wordList = this.getWordList();
        if (wordList.length === 0) {
            console.warn('词库为空');
            return;
        }

        const word = Utils.randomChoice(wordList);
        if (!word) return;
        this.currentWord = word;
        // 去除声调符号并转大写，用于与键盘输入匹配
        this.currentPinyin = Utils.normalizePinyinInput(word.pinyin);
        this.inputBuffer = '';
        this.inputIndex = 0;

        // 更新显示
        this.elements.hanzi.textContent = word.hanzi;
        this.elements.pinyinHint.textContent = this.showHint ? word.pinyin : '';
        this.elements.pinyinHint.style.opacity = this.showHint ? '1' : '0';
        this.elements.inputDisplay.textContent = '';

        // 高亮第一个字母
        if (this.currentPinyin.length > 0) {
            Keyboard.highlight(this.currentPinyin[0]);
        }

        // 朗读汉字
        this.schedule(() => {
            if (this.isRunning) Audio.speakPinyin(word.hanzi);
        }, 300);
    },

    /**
     * 处理按键
     */
    handleKeyPress(key) {
        if (!this.isRunning || !this.currentWord) return;

        const expectedKey = this.currentPinyin[this.inputIndex];

        if (key === expectedKey) {
            // 正确
            this.inputBuffer += key.toLowerCase();
            this.inputIndex++;

            Keyboard.showCorrect(key);
            Audio.playCorrect();

            // 更新输入显示
            this.updateInputDisplay();

            // 检查是否完成
            if (this.inputIndex >= this.currentPinyin.length) {
                this.completeWord();
            } else {
                // 高亮下一个字母
                Keyboard.highlight(this.currentPinyin[this.inputIndex]);
            }
        } else {
            // 错误
            Keyboard.showWrong(key);
            Audio.playWrong();

            if (this.onWrong) {
                this.onWrong();
            }
        }
    },

    /**
     * 更新输入显示
     */
    updateInputDisplay() {
        this.elements.inputDisplay.textContent = this.inputBuffer;
    },

    /**
     * 完成词语
     */
    completeWord() {
        const word = this.currentWord;

        // 显示完成效果
        this.elements.inputDisplay.style.animation = 'scaleBounce 0.5s ease';
        this.elements.hanzi.style.animation = 'scaleBounce 0.5s ease';

        // 拼读引导：先读拼音的各个部分，再读声调，最后读汉字
        // 例如：r en 的二声 人
        this.schedule(() => {
            if (!this.isRunning) return;
            // 解析拼音，分成声母和韵母部分
            const pinyinParts = this.parsePinyinParts(word.pinyin);
            // 获取声调
            const tone = this.getToneFromPinyin(word.pinyin);

            let delay = 0;
            // 依次朗读每个拼音部分
            pinyinParts.forEach((part, index) => {
                this.schedule(() => {
                    if (this.isRunning) Audio.speakPinyin(part, { interrupt: index === 0 });
                }, delay);
                delay += 500;
            });

            // 读声调（如果有的话）
            if (tone) {
                this.schedule(() => {
                    if (this.isRunning) Audio.speakPinyin(tone, { interrupt: false });
                }, delay);
                delay += 600;
            }

            // 最后朗读汉字
            this.schedule(() => {
                if (this.isRunning) Audio.speakPinyin(word.hanzi, { interrupt: false });
            }, delay + 300);
        }, 300);

        // 回调
        if (this.onCorrect) {
            this.onCorrect();
        }

        // 粒子效果
        Utils.createParticles(
            window.innerWidth / 2,
            window.innerHeight / 3,
            12,
            document.body
        );

        // 下一个词语（增加延迟以便完成拼读）
        this.schedule(() => {
            if (this.isRunning) {
                this.elements.inputDisplay.style.animation = '';
                this.elements.hanzi.style.animation = '';
                this.nextWord();
            }
        }, 4000);
    },

    /**
     * 从拼音中提取声调
     * 返回如 "的一声"、"的二声" 等
     */
    getToneFromPinyin(pinyin) {
        // 声调符号映射
        const toneMarks = {
            // 一声（阴平）
            'ā': 1, 'ē': 1, 'ī': 1, 'ō': 1, 'ū': 1, 'ǖ': 1,
            // 二声（阳平）
            'á': 2, 'é': 2, 'í': 2, 'ó': 2, 'ú': 2, 'ǘ': 2,
            // 三声（上声）
            'ǎ': 3, 'ě': 3, 'ǐ': 3, 'ǒ': 3, 'ǔ': 3, 'ǚ': 3,
            // 四声（去声）
            'à': 4, 'è': 4, 'ì': 4, 'ò': 4, 'ù': 4, 'ǜ': 4
        };

        const toneNames = {
            1: '一声',
            2: '二声',
            3: '三声',
            4: '四声'
        };

        // 查找拼音中的声调标记
        for (const char of pinyin) {
            if (toneMarks[char]) {
                return toneNames[toneMarks[char]];
            }
        }

        // 没有声调标记，可能是轻声
        return null;
    },

    /**
     * 解析拼音，分成声母和韵母部分
     * 例如：'rén' -> ['r', 'en'], 'xué xiào' -> ['x', 'ue', 'x', 'iao']
     */
    parsePinyinParts(pinyin) {
        // 去除声调
        const cleanPinyin = Utils.removePinyinTones(pinyin.toLowerCase());

        // 声母表
        const shengmu = ['zh', 'ch', 'sh', 'b', 'p', 'm', 'f', 'd', 't', 'n', 'l',
            'g', 'k', 'h', 'j', 'q', 'x', 'r', 'z', 'c', 's', 'y', 'w'];

        const parts = [];
        const syllables = cleanPinyin.split(/\s+/);

        syllables.forEach(syllable => {
            if (!syllable) return;

            // 尝试匹配声母
            let foundShengmu = null;
            for (const sm of shengmu) {
                if (syllable.startsWith(sm)) {
                    foundShengmu = sm;
                    break;
                }
            }

            if (foundShengmu) {
                parts.push(foundShengmu);
                const yunmu = syllable.slice(foundShengmu.length);
                if (yunmu) {
                    parts.push(yunmu);
                }
            } else {
                // 没有声母，整个是韵母（如 a, o, e, ai 等）
                parts.push(syllable);
            }
        });

        return parts;
    },

    /**
     * 切换提示显示
     */
    toggleHint() {
        this.showHint = !this.showHint;
        this.elements.pinyinHint.style.opacity = this.showHint ? '1' : '0';
    },

    /**
     * 设置年级
     */
    setGrade(grade) {
        this.grade = Math.max(1, Math.min(6, grade));
    },

    /**
     * 设置回调
     */
    setCallbacks({ onCorrect, onWrong }) {
        this.onCorrect = onCorrect || null;
        this.onWrong = onWrong || null;
    },

    isCurrentComplete() {
        return Boolean(this.currentWord) && this.inputIndex >= this.currentPinyin.length;
    },

    schedule(callback, delay) {
        const timer = setTimeout(() => {
            this.pendingTimers.delete(timer);
            callback();
        }, delay);
        this.pendingTimers.add(timer);
        return timer;
    },

    clearTimers() {
        this.pendingTimers.forEach(timer => clearTimeout(timer));
        this.pendingTimers.clear();
    }
};


/* --- js/game.js --- */
/* ===============================================
   游戏核心控制
   =============================================== */









const Game = {
    currentMode: null,
    currentUser: null,
    score: 0,
    correctCount: 0,
    wrongCount: 0,
    errorLetters: [],
    timeRemaining: 300,  // 5分钟 = 300秒
    timerInterval: null,
    pendingTimers: new Set(),
    restTimerInterval: null,
    restReminderTimeout: null,
    isPaused: false,
    isGameOver: false,
    currentSpeed: 0.5,

    /**
     * 初始化游戏
     */
    init() {
        // 初始化各个模块
        Audio.init();
        Keyboard.init('virtual-keyboard');
        LettersGame.init('game-canvas');
        PinyinGame.init();
        WordsGame.init();

        // 绑定按钮事件
        this.bindEvents();
    },

    /**
     * 绑定事件
     */
    bindEvents() {
        // 暂停按钮
        document.getElementById('btn-pause').addEventListener('click', () => {
            this.pause();
        });

        // 继续按钮
        document.getElementById('btn-resume').addEventListener('click', () => {
            this.resume();
        });

        // 退出按钮
        document.getElementById('btn-quit').addEventListener('click', () => {
            this.quit();
        });

        // 返回模式选择
        document.getElementById('btn-back-mode').addEventListener('click', () => {
            if (!this.isGameOver) {
                this.pause();
            } else {
                this.quit();
            }
        });

        // 再玩一次
        document.getElementById('btn-play-again').addEventListener('click', () => {
            this.playAgain();
        });

        // 返回菜单
        document.getElementById('btn-back-menu').addEventListener('click', () => {
            this.backToMenu();
        });

        // 休息完成
        document.getElementById('btn-rest-done').addEventListener('click', () => {
            this.hideRestReminder();
        });

        // 速度控制
        document.getElementById('btn-speed-up').addEventListener('click', () => {
            this.changeSpeed(0.1);
        });

        document.getElementById('btn-speed-down').addEventListener('click', () => {
            this.changeSpeed(-0.1);
        });

        // 语言切换按钮
        document.getElementById('btn-lang-toggle').addEventListener('click', () => {
            this.toggleLetterLanguage();
        });
    },

    /**
     * 切换字母读音语言
     */
    toggleLetterLanguage() {
        const newLang = Audio.toggleLetterLanguage();
        this.updateLanguageDisplay(newLang);

        // 播放示例音效，让用户听到变化
        Audio.speakLetter('A');
    },

    /**
     * 更新语言显示
     */
    updateLanguageDisplay(lang) {
        const btn = document.getElementById('btn-lang-toggle');
        const langText = document.getElementById('lang-text');

        if (lang === 'zh') {
            btn.classList.add('zh-mode');
            langText.textContent = '中';
        } else {
            btn.classList.remove('zh-mode');
            langText.textContent = 'EN';
        }
    },

    /**
     * 开始游戏
     */
    start(mode) {
        if (!['letters', 'pinyin', 'words'].includes(mode)) return;

        this.stopAllGames();
        this.hideRestReminder();
        this.currentMode = mode;
        this.currentUser = Storage.getCurrentUser();
        if (!this.currentUser) {
            this.currentMode = null;
            return;
        }
        this.score = 0;
        this.correctCount = 0;
        this.wrongCount = 0;
        this.errorLetters = [];
        this.timeRemaining = 300;
        this.isPaused = false;
        this.isGameOver = false;
        this.currentSpeed = 0.5;

        // 更新UI
        this.updateScoreDisplay();
        this.updateTimerDisplay();
        this.updateSpeedDisplay();
        this.updateLanguageDisplay(Audio.getLetterLanguage());

        // 显示游戏界面
        this.showScreen('game-screen');

        // 根据模式启动对应游戏
        switch (mode) {
            case 'letters':
                this.startLettersGame();
                break;
            case 'pinyin':
                this.startPinyinGame();
                break;
            case 'words':
                this.startWordsGame();
                break;
        }

        // 开始倒计时
        this.startTimer();

        // 恢复音频上下文
        Audio.resume();
        Audio.primeVoicePlayback();

        // 语音引导
        this.schedule(() => Audio.speakGuide('游戏开始！'), 500);
    },

    /**
     * 开始字母森林游戏
     */
    startLettersGame() {
        // 显示 Canvas，隐藏其他
        document.getElementById('game-canvas').style.display = 'block';
        document.getElementById('pinyin-display').style.display = 'none';
        document.getElementById('word-display').style.display = 'none';

        // 显示语言切换按钮（只在字母森林模式显示）
        document.getElementById('btn-lang-toggle').style.display = 'flex';

        // 设置回调
        LettersGame.setCallbacks({
            onCorrect: (letter, x, y) => {
                this.addScore(10);
                this.correctCount++;
                this.updateScoreDisplay();
            },
            onWrong: (letter) => {
                this.addScore(-5);
                this.wrongCount++;
                this.errorLetters.push(letter);
                this.updateScoreDisplay();
            },
            onMiss: (letter) => {
                this.addScore(-5);
                this.wrongCount++;
                this.errorLetters.push(letter);
                this.updateScoreDisplay();
            }
        });

        // 开始游戏
        LettersGame.start();

        // 应用初始速度
        LettersGame.setSpeed(this.currentSpeed);
    },

    /**
     * 开始拼音合成室游戏
     */
    startPinyinGame() {
        document.getElementById('game-canvas').style.display = 'none';
        document.getElementById('pinyin-display').style.display = 'flex';
        document.getElementById('word-display').style.display = 'none';

        // 隐藏语言切换按钮（拼音模式只用中文拼音发音）
        document.getElementById('btn-lang-toggle').style.display = 'none';

        PinyinGame.setCallbacks({
            onCorrect: () => {
                this.addScore(15);
                this.correctCount++;
                this.updateScoreDisplay();
            },
            onWrong: () => {
                this.addScore(-5);
                this.wrongCount++;
                this.updateScoreDisplay();
            }
        });

        PinyinGame.start();
    },

    /**
     * 开始词语竞速游戏
     */
    startWordsGame() {
        document.getElementById('game-canvas').style.display = 'none';
        document.getElementById('pinyin-display').style.display = 'none';
        document.getElementById('word-display').style.display = 'block';

        // 隐藏语言切换按钮（词语模式只用中文朗读）
        document.getElementById('btn-lang-toggle').style.display = 'none';

        WordsGame.setCallbacks({
            onCorrect: () => {
                this.addScore(20);
                this.correctCount++;
                this.updateScoreDisplay();
            },
            onWrong: () => {
                this.addScore(-5);
                this.wrongCount++;
                this.updateScoreDisplay();
            }
        });

        WordsGame.start();
    },

    /**
     * 添加分数
     */
    addScore(points) {
        this.score = Math.max(0, this.score + points);
    },

    /**
     * 更新分数显示
     */
    updateScoreDisplay() {
        document.getElementById('score').textContent = this.score;
        document.getElementById('correct-count').textContent = this.correctCount;
        document.getElementById('wrong-count').textContent = this.wrongCount;
    },

    /**
     * 开始计时器
     */
    startTimer() {
        if (this.timerInterval) clearInterval(this.timerInterval);
        this.timerInterval = setInterval(() => {
            if (this.isPaused || this.isGameOver) return;

            this.timeRemaining--;
            this.updateTimerDisplay();

            // 警告音效
            if (this.timeRemaining === 60) {
                Audio.speakGuide('还剩一分钟！');
            } else if (this.timeRemaining <= 10 && this.timeRemaining > 0) {
                Audio.playTimerWarning();
            }

            // 时间到
            if (this.timeRemaining <= 0) {
                this.gameOver();
            }
        }, 1000);
    },

    /**
     * 更新计时器显示
     */
    updateTimerDisplay() {
        const timerEl = document.getElementById('timer');
        timerEl.textContent = Utils.formatTime(this.timeRemaining);

        // 添加警告样式
        timerEl.classList.remove('timer-warning', 'timer-critical');
        if (this.timeRemaining <= 30) {
            timerEl.classList.add('timer-critical');
        } else if (this.timeRemaining <= 60) {
            timerEl.classList.add('timer-warning');
        }
    },

    /**
     * 暂停游戏
     */
    pause() {
        if (this.isGameOver || this.isPaused || !this.currentMode) return;
        this.isPaused = true;
        document.getElementById('pause-modal').style.display = 'flex';

        // 暂停当前游戏
        switch (this.currentMode) {
            case 'letters':
                LettersGame.pause();
                break;
            case 'pinyin':
                PinyinGame.pause();
                break;
            case 'words':
                WordsGame.pause();
                break;
        }
    },

    /**
     * 继续游戏
     */
    resume() {
        if (!this.isPaused || this.isGameOver) return;
        this.isPaused = false;
        document.getElementById('pause-modal').style.display = 'none';

        // 继续当前游戏
        switch (this.currentMode) {
            case 'letters':
                LettersGame.resume();
                break;
            case 'pinyin':
                PinyinGame.resume();
                break;
            case 'words':
                WordsGame.resume();
                break;
        }
    },

    /**
     * 退出游戏
     */
    quit() {
        this.stopAllGames();
        this.hideRestReminder();
        this.currentMode = null;
        this.isPaused = false;
        this.isGameOver = false;
        this.showScreen('mode-screen');
    },

    /**
     * 停止所有游戏
     */
    stopAllGames() {
        if (this.timerInterval) {
            clearInterval(this.timerInterval);
            this.timerInterval = null;
        }

        this.clearTimers();

        LettersGame.stop();
        PinyinGame.stop();
        WordsGame.stop();
        Audio.stopSpeaking();

        document.getElementById('pause-modal').style.display = 'none';
    },

    /**
     * 游戏结束
     */
    gameOver() {
        if (this.isGameOver || !this.currentUser || !this.currentMode) return;
        this.isGameOver = true;
        this.stopAllGames();

        // 保存结果
        const result = Storage.recordGameResult(
            this.currentUser.id,
            this.currentMode,
            this.score,
            this.correctCount,
            this.wrongCount,
            this.errorLetters
        );

        if (!result?.user) {
            this.quit();
            return;
        }

        this.currentUser = result.user;
        void Api.syncGameResult({
            userId: this.currentUser.id,
            mode: this.currentMode,
            score: this.score,
            correct: this.correctCount,
            wrong: this.wrongCount,
            errorLetters: this.errorLetters
        });
        document.dispatchEvent(new CustomEvent('pinyin:user-updated', {
            detail: { user: this.currentUser }
        }));

        // 更新UI
        const resultMessage = Utils.getResultMessage(this.score, this.correctCount, this.wrongCount);
        document.getElementById('result-title').textContent = resultMessage.title;
        document.getElementById('final-score').textContent = this.score;
        document.getElementById('final-correct').textContent = this.correctCount;
        document.getElementById('final-wrong').textContent = this.wrongCount;

        // 显示新勋章
        const badgeEl = document.getElementById('badge-earned');
        if (result.newBadge) {
            badgeEl.style.display = 'block';
            document.getElementById('badge-icon').textContent = result.newBadge.icon;
            document.getElementById('badge-name').textContent = result.newBadge.name;
            Audio.playBadgeUnlock();
            Utils.createConfetti();
        } else {
            badgeEl.style.display = 'none';
        }

        // 播放音效
        if (this.score >= 200) {
            Audio.playVictory();
        } else {
            Audio.playGameOver();
        }

        // 显示结算界面
        this.showScreen('result-screen');

        // 检查防沉迷
        const gameCount = Storage.incrementGameCount();
        if (gameCount >= 2) {
            this.restReminderTimeout = setTimeout(() => {
                this.restReminderTimeout = null;
                this.showRestReminder();
            }, 2000);
        }
    },

    /**
     * 显示休息提醒
     */
    showRestReminder() {
        if (this.restTimerInterval) clearInterval(this.restTimerInterval);
        const modal = document.getElementById('rest-modal');
        const timerEl = document.getElementById('rest-timer');
        const btnDone = document.getElementById('btn-rest-done');

        modal.style.display = 'flex';
        btnDone.disabled = true;

        let restTime = 10;
        timerEl.textContent = restTime;

        this.restTimerInterval = setInterval(() => {
            restTime--;
            timerEl.textContent = restTime;

            if (restTime <= 0) {
                clearInterval(this.restTimerInterval);
                this.restTimerInterval = null;
                btnDone.disabled = false;
                Storage.resetGameCount();
            }
        }, 1000);
    },

    /**
     * 再玩一次
     */
    playAgain() {
        if (this.currentMode) this.start(this.currentMode);
    },

    /**
     * 返回菜单
     */
    backToMenu() {
        this.stopAllGames();
        this.hideRestReminder();
        this.isPaused = false;
        this.isGameOver = false;
        this.showScreen('mode-screen');
    },

    /**
     * 显示指定界面
     */
    showScreen(screenId) {
        document.querySelectorAll('.screen').forEach(screen => {
            screen.classList.remove('active');
        });
        document.getElementById(screenId).classList.add('active');
    },

    /**
     * 调整游戏速度
     */
    changeSpeed(delta) {
        let newSpeed = Math.round((this.currentSpeed + delta) * 10) / 10;
        newSpeed = Math.max(0.5, Math.min(2.0, newSpeed));

        if (newSpeed !== this.currentSpeed) {
            this.currentSpeed = newSpeed;
            this.updateSpeedDisplay();
            this.applySpeed();
        }
    },

    /**
     * 更新速度显示
     */
    updateSpeedDisplay() {
        document.getElementById('speed-value').textContent = this.currentSpeed.toFixed(1) + 'x';
        document.getElementById('btn-speed-up').disabled = this.currentSpeed >= 2.0;
        document.getElementById('btn-speed-down').disabled = this.currentSpeed <= 0.5;
    },

    /**
     * 应用速度设置
     */
    applySpeed() {
        if (this.currentMode === 'letters') {
            LettersGame.setSpeed(this.currentSpeed);
        }
        // 未来可以支持其他模式
    },

    schedule(callback, delay) {
        const timer = setTimeout(() => {
            this.pendingTimers.delete(timer);
            callback();
        }, delay);
        this.pendingTimers.add(timer);
        return timer;
    },

    clearTimers() {
        this.pendingTimers.forEach(timer => clearTimeout(timer));
        this.pendingTimers.clear();
    },

    hideRestReminder() {
        if (this.restReminderTimeout) {
            clearTimeout(this.restReminderTimeout);
            this.restReminderTimeout = null;
        }
        if (this.restTimerInterval) {
            clearInterval(this.restTimerInterval);
            this.restTimerInterval = null;
        }
        const modal = document.getElementById('rest-modal');
        const btnDone = document.getElementById('btn-rest-done');
        if (modal) modal.style.display = 'none';
        if (btnDone) btnDone.disabled = true;
    }
};


/* --- js/main.js --- */
/* ===============================================
   主入口
   =============================================== */





const Main = {
    currentUser: null,
    selectedAvatar: null,
    currentHelpMode: null,

    /**
     * 初始化应用
     */
    init() {
        Api.init();
        // 初始化游戏模块
        Game.init();

        // 绑定UI事件
        this.bindEvents();

        // 加载已有用户
        this.loadExistingUsers();

        // 检查是否有当前用户
        const currentUser = Storage.getCurrentUser();
        if (currentUser) {
            this.currentUser = currentUser;
            this.showScreen('mode-screen');
            this.updateUserInfo();
            this.updateModeCards();
        }

        document.addEventListener('pinyin:user-updated', (event) => {
            this.currentUser = event.detail?.user || null;
            this.updateUserInfo();
            this.updateModeCards();
            this.loadExistingUsers();
        });

        console.log('🎮 拼音探险家已加载！');
    },

    /**
     * 绑定事件
     */
    bindEvents() {
        // 头像选择
        document.querySelector('.avatar-grid').addEventListener('click', (event) => {
            const avatarButton = event.target.closest('.avatar-btn');
            if (avatarButton) this.selectAvatar(avatarButton.dataset.avatar);
        });

        // 开始冒险按钮
        document.getElementById('btn-enter').addEventListener('click', () => {
            this.handleEnter();
        });

        // 返回开始界面
        document.getElementById('btn-back-start').addEventListener('click', () => {
            this.showScreen('start-screen');
        });

        // 帮助按钮
        document.querySelectorAll('.btn-help').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();  // 阻止冒泡，防止触发模式选择
                const mode = btn.dataset.mode;
                this.showHelp(mode);
            });
        });

        // 关闭帮助弹窗
        document.getElementById('btn-close-help').addEventListener('click', () => {
            this.hideHelp();
        });

        // 从帮助弹窗开始游戏
        document.getElementById('btn-start-game').addEventListener('click', () => {
            const currentMode = this.currentHelpMode;
            this.hideHelp();
            if (currentMode) {
                this.startGame(currentMode);
            }
        });

        // 模式选择
        document.querySelectorAll('.mode-card').forEach(card => {
            card.addEventListener('click', () => {
                if (!card.classList.contains('locked')) {
                    const mode = card.dataset.mode;
                    this.startGame(mode);
                } else {
                    Audio.playWrong();
                    card.style.animation = 'shake 0.3s ease';
                    setTimeout(() => card.style.animation = '', 300);
                }
            });
        });

        // 已有用户选择
        document.getElementById('user-list').addEventListener('click', (e) => {
            const userItem = e.target.closest('.user-item');
            if (userItem) {
                document.querySelectorAll('.user-item').forEach(item => item.classList.remove('selected'));
                userItem.classList.add('selected');

                const userId = userItem.dataset.userId;
                this.currentUser = Storage.getUser(userId);
                if (!this.currentUser) {
                    this.loadExistingUsers();
                    return;
                }
                Storage.setCurrentUser(userId);

                // 清除新用户输入
                document.getElementById('username').value = '';
                document.querySelectorAll('.avatar-btn').forEach(button => {
                    button.classList.remove('selected');
                    button.setAttribute('aria-pressed', 'false');
                });
                this.selectedAvatar = null;

                Audio.playCorrect();
            }
        });

        // 用户名输入时取消选中已有用户
        document.getElementById('username').addEventListener('input', () => {
            document.querySelectorAll('.user-item').forEach(item => item.classList.remove('selected'));
        });
    },

    /**
     * 选择头像，并清除已有玩家选择，避免两种入口同时生效。
     */
    selectAvatar(avatar) {
        const avatarButton = document.querySelector(`.avatar-btn[data-avatar="${avatar}"]`);
        if (!avatarButton) return;

        document.querySelectorAll('.avatar-btn').forEach(button => {
            const selected = button === avatarButton;
            button.classList.toggle('selected', selected);
            button.setAttribute('aria-pressed', String(selected));
        });
        document.querySelectorAll('.user-item').forEach(item => item.classList.remove('selected'));
        this.selectedAvatar = avatar;
        Audio.playKeyPress();
    },

    /**
     * 显示帮助弹窗
     */
    showHelp(mode) {
        this.currentHelpMode = mode;

        // 隐藏所有帮助内容
        document.getElementById('help-letters').style.display = 'none';
        document.getElementById('help-pinyin').style.display = 'none';
        document.getElementById('help-words').style.display = 'none';

        // 显示对应模式的帮助内容
        document.getElementById(`help-${mode}`).style.display = 'block';

        // 检查模式是否锁定
        const isLocked = this.isModeLocked(mode);
        const startBtn = document.getElementById('btn-start-game');
        const requiredScores = { letters: 0, pinyin: 500, words: 1500 };

        if (isLocked) {
            const requiredScore = requiredScores[mode] ?? 0;
            startBtn.textContent = `🔒 需要 ${requiredScore} 分解锁`;
            startBtn.disabled = true;
            startBtn.classList.add('btn-disabled');
        } else {
            startBtn.textContent = '🚀 开始游戏';
            startBtn.disabled = false;
            startBtn.classList.remove('btn-disabled');
        }

        // 显示弹窗
        document.getElementById('help-modal').style.display = 'flex';

        Audio.playKeyPress();
    },

    /**
     * 检查模式是否锁定，卡片和帮助弹窗共用同一套规则。
     */
    isModeLocked(mode) {
        const user = this.currentUser || Storage.getCurrentUser();
        const requiredScores = { letters: 0, pinyin: 500, words: 1500 };
        return !user || (user.totalScore || 0) < (requiredScores[mode] ?? Number.MAX_SAFE_INTEGER);
    },

    /**
     * 隐藏帮助弹窗
     */
    hideHelp() {
        document.getElementById('help-modal').style.display = 'none';
        this.currentHelpMode = null;
    },

    /**
     * 加载已有用户
     */
    loadExistingUsers() {
        const users = Storage.getUsers();
        const container = document.getElementById('existing-users');
        const list = document.getElementById('user-list');

        if (users.length === 0) {
            container.style.display = 'none';
            return;
        }

        container.style.display = 'block';
        list.replaceChildren();

        users.forEach(user => {
            const avatarEmoji = this.getAvatarEmoji(user.avatar);
            const item = document.createElement('div');
            item.className = 'user-item';
            item.dataset.userId = user.id;

            const avatar = document.createElement('span');
            avatar.className = 'user-item-avatar';
            avatar.textContent = avatarEmoji;

            const name = document.createElement('span');
            name.className = 'user-item-name';
            name.textContent = user.name;

            const score = document.createElement('span');
            score.className = 'user-item-score';
            score.textContent = `🏆 ${user.totalScore}`;

            item.append(avatar, name, score);
            list.appendChild(item);
        });
    },

    /**
     * 获取头像 emoji
     */
    getAvatarEmoji(avatar) {
        const avatars = {
            'cat': '🐱',
            'dog': '🐶',
            'rabbit': '🐰',
            'bear': '🐻',
            'panda': '🐼',
            'fox': '🦊'
        };
        return avatars[avatar] || '🐱';
    },

    /**
     * 处理进入游戏
     */
    handleEnter() {
        const username = document.getElementById('username').value.trim();

        // 检查是否选择了已有用户
        const selectedExisting = document.querySelector('.user-item.selected');
        if (selectedExisting) {
            const userId = selectedExisting.dataset.userId;
            this.currentUser = Storage.getUser(userId);
            if (!this.currentUser) {
                this.loadExistingUsers();
                return;
            }
            Storage.setCurrentUser(userId);
        } else if (username && this.selectedAvatar) {
            // 创建新用户
            this.currentUser = Storage.createUser(username, this.selectedAvatar);
            if (!this.currentUser) return;
        } else {
            // 提示选择
            Audio.playWrong();
            if (!this.selectedAvatar) {
                Audio.speakGuide('请选择一个头像');
            } else if (!username) {
                Audio.speakGuide('请输入你的名字');
            }
            return;
        }

        Audio.playCorrect();
        Audio.speakGuide(`你好, ${this.currentUser.name}`);

        this.showScreen('mode-screen');
        this.updateUserInfo();
        this.updateModeCards();
    },

    /**
     * 更新用户信息显示
     */
    updateUserInfo() {
        if (!this.currentUser) return;

        document.getElementById('current-avatar').textContent = this.getAvatarEmoji(this.currentUser.avatar);
        document.getElementById('current-name').textContent = this.currentUser.name;
        document.getElementById('total-score').textContent = this.currentUser.totalScore;
    },

    /**
     * 更新模式卡片锁定状态
     */
    updateModeCards() {
        const totalScore = this.currentUser?.totalScore || 0;
        const requiredScores = { letters: 0, pinyin: 500, words: 1500 };

        document.querySelectorAll('.mode-card').forEach(card => {
            const mode = card.dataset.mode;
            const locked = totalScore < (requiredScores[mode] ?? Number.MAX_SAFE_INTEGER);
            card.classList.toggle('locked', locked);
            card.setAttribute('aria-disabled', String(locked));

            const lockOverlay = card.querySelector('.lock-overlay');
            if (lockOverlay) lockOverlay.style.display = locked ? 'flex' : 'none';
        });
    },

    /**
     * 开始游戏
     */
    startGame(mode) {
        if (!this.currentUser || this.isModeLocked(mode)) {
            Audio.playWrong();
            return;
        }
        Audio.playCorrect();
        Game.start(mode);
    },

    /**
     * 显示指定界面
     */
    showScreen(screenId) {
        document.querySelectorAll('.screen').forEach(screen => {
            screen.classList.remove('active');
        });
        const target = document.getElementById(screenId);
        if (target) target.classList.add('active');
    }
};

// DOM 加载完成后初始化
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => Main.init(), { once: true });
} else {
    Main.init();
}

